/// <summary>
///    Finds the specified record in the <c>KCS_KBVInquirerOfTheRequest</c> table.
/// </summary>
/// <param name="_requestId">
///    The record ID of the <c>KCS_KBVInquirerOfTheRequest</c> record to find.
/// </param>
/// <param name="_forUpdate">
///    A Boolean value that indicates whether to read the record for update; optional.
/// </param>
/// <param name="_projectId">
///    The project ID of the <c>KCS_KBVBuildingProjectID</c> record to find.
/// </param>
/// <param name="_dirPartId">
///    The DirPArtyTable ID of the <c>DirPartyRecId</c> record to find.
/// </param>
/// <returns>
///    A record in the <c>KCS_KBVInquirerOfTheRequest</c> table; otherwise, an empty record.
/// </returns>
public static KCS_KBVRequestTable find( KCS_KBVRequestId            _requestId,
                                        boolean                     _forUpdate  = false,
                                        KCS_KBVBuildingProjectID    _projectId  = '',
                                        DirPartyRecId               _dirPartId  = 0 )
{
    KCS_KBVRequestTable record;

    if (_requestId)
    {
        record.selectForUpdate(_forUpdate);

        if (_projectId && _dirPartId)
        {
            select firstonly record
            where   record.KCS_KBVRequestId         == _requestId;
        }
        else if (_projectId)
        {
            select firstonly record
            where   record.KCS_KBVBuildingProjectID == _projectId;
        }
        else if (_dirPartId)
        {
            select firstonly record
            where   record.dirPartyId               == _dirPartId;
        }
    }

    return record;
}

/// <summary>
///    AVA <c>findRecId</c> method.
/// </summary>
/// <param name="_recordId">
///    <c>RecId</c> as type
/// </param>
/// <param name="_forUpdate">
///    <c>boolean</c> as type
/// </param>
/// <returns>
///    <c>KCS_KBVRequestTable</c> as return value
/// </returns>
public static KCS_KBVRequestTable findRecId(RecId    _recordId,
                                            boolean  _forUpdate = false)
{
    KCS_KBVRequestTable record;

    if (_recordId)
    {
        record.selectForUpdate(_forUpdate);

        select firstonly RecId
        from    record
        where   record.RecId == _recordId;
    }

    return record;
}

/// <summary>
///     Check existance of record in the <c>KCS_KBVInquirerOfTheRequest</c> table
/// </summary>
/// <param name = "_recordId">
///     The record ID of the <c>KCS_KBVInquirerOfTheRequest</c> record to check.
/// </param>
/// <returns>
///     <c>boolean</c> true if record exists
/// </returns>
static boolean  exist(RecId _recordId)
{
    return  _recordId 
        &&  (select firstonly RecId 
            from    KCS_KBVRequestTable
            where   KCS_KBVRequestTable.RecId == _recordId).RecId;
}

