///    <c>DirPartyTable</c> as return value
/// </returns>
public DirPartyTable dirPartyTablePrefered()
{
    DirPartyTable retVal;

    retVal = this.dirPartyTablePerson();
    if(!retVal.RecId)
    {
        retVal = this.dirPartyTableOrganization();
    }

    return retVal;
}

