/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_fieldId">_fieldId</param>
public void modifiedField(FieldId _fieldId)
{
    KCS_KBVRequestTable locKCS_KBVRequestTable;

    super(_fieldId);

    switch(_fieldId)
    {
        case fieldNum(KCS_KBVInquirerOfTheRequest,DirPartyId):
            smmBusRelTable      checkSmmBusRelTable;
            checkSmmBusRelTable = smmBusRelTable::findByParty(this.DirPartyId);
            if (!checkSmmBusRelTable.RecId)
            {
                KCS_KBVRelationsToBV::createSmmBusRelTableForCompany(this.DirPartyId);
            }

            KCS_KBVSearchTable::setFromCommonField(this.KCS_KBVBuildingProjectID,this,_fieldId);
            break;

        case fieldNum(KCS_KBVInquirerOfTheRequest,ContactPersonId):
            KCS_KBVSearchTable::setFromCommonField(this.KCS_KBVBuildingProjectID,this,_fieldId);
            break;

        case fieldNum(KCS_KBVInquirerOfTheRequest, KCS_KBVRequestID):
            if(     this.KCS_KBVRequestID
                &&  this.KCS_KBVRequestID != this.orig().KCS_KBVRequestID   )
            {
                this.KCS_KBVBuildingProjectID = KCS_KBVRequestTable::find(this.KCS_KBVRequestID).KCS_KBVBuildingProjectID;
            }
            break;

        case fieldNum(KCS_KBVInquirerOfTheRequest, KCS_KBVBuildingProjectID):
            if(     this.KCS_KBVBuildingProjectID
                &&  this.KCS_KBVBuildingProjectID != this.orig().KCS_KBVBuildingProjectID   )
            {
                if(this.KCS_KBVRequestID)
                {
                    locKCS_KBVRequestTable = KCS_KBVRequestTable::find(this.KCS_KBVRequestID);
                    if(locKCS_KBVRequestTable.RecId && locKCS_KBVRequestTable.KCS_KBVBuildingProjectID != this.KCS_KBVBuildingProjectID)
                    {
                        this.KCS_KBVRequestID = '';
                    }
                }
            }
            break;

        default:
            break;
    }

}

/// <summary>
/// designed from AVA
/// </summary>
public void insert()
{
    if(this.KCS_KBVRequestID && this.KCS_KBVBuildingProjectID == '')
    {
        this.KCS_KBVBuildingProjectID = KCS_KBVRequestTable::find(this.KCS_KBVRequestID).KCS_KBVBuildingProjectID;
    }

    super();

    KCS_KBVSearchTable::setFromCommonField(this.KCS_KBVBuildingProjectID,this,fieldnum(KCS_KBVInquirerOfTheRequest,DirPartyId));
    KCS_KBVSearchTable::setFromCommonField(this.KCS_KBVBuildingProjectID,this,fieldNum(KCS_KBVInquirerOfTheRequest,ContactPersonId));
}

/// <summary>
///    AVA <c>editContactPersonName</c> method.
/// </summary>
/// <param name="_set">
///    <c>boolean</c> as type
/// </param>
/// <param name="_name">
///    <c>ContactPersonName</c> as type
/// </param>
/// <returns>
///    <c>ContactPersonName</c> as return value
/// </returns>
edit ContactPersonName  editContactPersonName(boolean _set, ContactPersonName _name)
{
    ContactPersonName                   retVal;

    AVAKBVDirPartyContactPersonHelper   locAVAKBVDirPartyContactPersonHelper;

    if(_set)
    {
        locAVAKBVDirPartyContactPersonHelper = new AVAKBVDirPartyContactPersonHelper();

        locAVAKBVDirPartyContactPersonHelper.parmSet(_set);
        locAVAKBVDirPartyContactPersonHelper.parmDataAreaId(curExt());
        locAVAKBVDirPartyContactPersonHelper.parmDirPartyId(this.DirPartyId);
        locAVAKBVDirPartyContactPersonHelper.parmDirPartyName('');
        //locAVAKBVDirPartyContactPersonHelper.parmContactPersonId(this.ContactPersonId);
        locAVAKBVDirPartyContactPersonHelper.parmContactPersonId(_name);
        //locAVAKBVDirPartyContactPersonHelper.parmContactPersonName(_name);
        locAVAKBVDirPartyContactPersonHelper.parmContactPersonName(ContactPerson::find(_name).personName());

        retVal = locAVAKBVDirPartyContactPersonHelper.getEditContactPersonName();

        this.ContactPersonId = locAVAKBVDirPartyContactPersonHelper.parmContactPersonId();
        KCS_KBVSearchTable::setFromCommonField( this.KCS_KBVBuildingProjectID,
                                                this, 
                                                fieldNum(KCS_KBVInquirerOfTheRequest, ContactPersonId)  );

        if(locAVAKBVDirPartyContactPersonHelper.parmRefresh())
        {
            if (FormDataUtil::getFormDataSource(this))
            {
                FormDataUtil::getFormDataSource(this).refresh();
            }
        }
    }
    else
    {
        retVal =ContactPerson::find(this.ContactPersonId).personName();
    }

    return retVal;
}
